using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.test;
using ghidra.test;

public class ToolConnectionTest : AbstractGhidraHeadedIntegrationTest {

	private FrontEndTool frontEndTool;
	private TestEnv env;
	private ToolConnectionDialog dialog;
	private JList<object> producerList;
	private JList<object> consumerList;
	private JList<object> eventList;

	private PluginTool tool1;
	private PluginTool tool2;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		env.resetDefaultTools();
		frontEndTool = env.getFrontEndTool();
		env.showFrontEndTool();
		setErrorGUIEnabled(false);

		tool1 = runTool("CodeBrowser");
		tool2 = runTool("CodeBrowser");
	}

	private Program buildNotepad()
    {
		ProgramBuilder builder = new ProgramBuilder("notepad", ProgramBuilder._TOY);
		builder.createMemory("test2", "0x1001000", 0x2000);
		Program p = builder.getProgram();
		p.clearUndo();
		return p;
	}

	/* @After */
	public void tearDown()
    {
		if (dialog != null) {
			close(dialog);
		}

		env.dispose();

		closeAllWindows();
	}

	/* @Test */
	public void testConnectToolsDialog()
    {

		connectTools();

		int eventCount = eventList.getModel().getSize();
		for (int i = 0; i < eventCount; i++) {
			clickListRow(eventList, i);
		}

		pressButtonByText(dialog, "OK");

		Program p = buildNotepad();

		ProgramManager pm = tool1.getService(typeof(ProgramManager));
		runSwing(() => pm.openProgram(p.getDomainFile()));

		waitForSwing();

		ProgramManager pm2 = tool2.getService(typeof(ProgramManager));
		assertNull(pm2.getCurrentProgram());

		// open same program in second tool - cannot rely on tool connection for this
		tool2.firePluginEvent(new OpenProgramPluginEvent("Test", p));

		waitForSwing();

		assertEquals(p, pm2.getCurrentProgram());

		Address a = p.getAddressFactory().getDefaultAddressSpace().getAddress(0x1001010);

		CodeBrowserPlugin cb1 = getPlugin(tool1, typeof(CodeBrowserPlugin));
		cb1.goTo(new ProgramLocation(p, a), true);

		waitForSwing();

		CodeBrowserPlugin cb2 = getPlugin(tool2, typeof(CodeBrowserPlugin));
		ProgramLocation loc = cb2.getCurrentLocation();
		assertNotNull(loc);
		assertEquals(a, loc.getAddress());

	}

	/* @Test */
	public void testPluginsRemoved()
    {

		connectTools();

		JCheckBox cb = (JCheckBox) eventList.getModel().getElementAt(0);
		assertTrue(cb.getText().equals("ByteBlockChange"));
		close(dialog);

		Plugin p1 = getPlugin(tool1, typeof(ByteViewerPlugin));
		removePlugin(tool1, p1);

		Plugin p2 = getPlugin(tool2, typeof(ByteViewerPlugin));
		removePlugin(tool2, p2);

		connectTools();

		cb = (JCheckBox) eventList.getModel().getElementAt(0);
		assertTrue(!cb.getText().equals("ByteBlockChange"));
	}

	/* @Test */
	public void testPluginsAdded()
    {

		connectTools();

		JCheckBox cb = (JCheckBox) eventList.getModel().getElementAt(0);
		assertTrue(cb.getText().equals("ByteBlockChange"));
		close(dialog);

		Plugin p1 = getPlugin(tool1, typeof(ByteViewerPlugin));
		removePlugin(tool1, p1);

		Plugin p2 = getPlugin(tool2, typeof(ByteViewerPlugin));
		removePlugin(tool2, p2);

		connectTools();

		cb = (JCheckBox) eventList.getModel().getElementAt(0);
		assertTrue(!cb.getText().equals("ByteBlockChange"));
		close(dialog);

		// add ByteViewer back in 
		addPlugin(tool1, typeof(ByteViewerPlugin).getName());
		addPlugin(tool2, typeof(ByteViewerPlugin).getName());

		connectTools();

		cb = (JCheckBox) eventList.getModel().getElementAt(0);
		assertTrue(cb.getText().equals("ByteBlockChange"));
		close(dialog);
	}

//==================================================================================================
// Private Methods
//==================================================================================================	

	private void clickListRow(JList<object> list, int row) {

		AtomicReference<Rectangle> @ref = new();
		runSwing(() => @ref.set(list.getCellBounds(row, row)));

		Rectangle rect = @ref.get();
		clickMouse(list, 1, rect.x + 5, rect.y + 5, 1, 0);
	}

	private void connectTools()
    {
		DockingActionIf connectAction = getAction("Connect Tools");
		performAction(connectAction, true);
		dialog = waitForDialogComponent(typeof(ToolConnectionDialog));
		producerList = (JList<object>) findComponentByName(dialog, "Producers");
		consumerList = (JList<object>) findComponentByName(dialog, "Consumers");
		eventList = (JList<object>) findComponentByName(dialog, "Events");

		assertNotNull(producerList);
		assertNotNull(consumerList);
		assertNotNull(eventList);

		selectListItem(producerList, 0);
		selectListItem(consumerList, 1);
	}

	private void selectListItem(JList<object> list, int index)
    {
		runSwing(() => list.setSelectedIndex(index));
	}

	private void addPlugin(PluginTool tool, string className)
    {
		runSwing(() => {
			try {
				tool.addPlugin(className);
			}
			catch (PluginException e) {
				e.printStackTrace();
			}
			tool.getProject().getToolManager().toolChanged(tool);
		});
	}

	private void removePlugin(PluginTool tool, Plugin plugin)
    {
		runSwing(() => {
			tool.removePlugins(List.of(plugin));
			tool.getProject().getToolManager().toolChanged(tool);
		});
	}

	private DockingActionIf getAction(string actionName) {
		DockingActionIf action = getAction(frontEndTool, "FrontEndPlugin", actionName);
		return action;
	}

	private DockingActionIf getAction(string toolName, string action) {

		Set<DockingActionIf> actions =
			getActionsByOwnerAndName(frontEndTool, "FrontEndPlugin", toolName);
		foreach (DockingActionIf a in actions) {
			string[] menuPath = a.getMenuBarData().getMenuPath();
			if (menuPath.length > 2) {
				if (menuPath[1].indexOf(action) >= 0) {
					return a;
				}
			}
		}
		return null;
	}

	private PluginTool runTool(string toolName)
    {
		DockingActionIf runAction = getAction(toolName, "Run Tool");
		assertNotNull(runAction);// if action is null, the name of the tool changed
		performAction(runAction, toolName, true);
		PluginTool[] tools = frontEndTool.getToolServices().getRunningTools();
		return tools[tools.length - 1];
	}

	private void performAction(DockingActionIf action, string name, bool doWait)
    {

		JMenuItem item = new JMenuItem(name);
		Runnable r = () => action.actionPerformed(new DefaultActionContext(null, null, item));
		runSwing(r, doWait);
		waitForSwing();
	}

}
